import importlib
import logging
import re
from ute_ue.lteue import LteUe
from ute_common_abstract_core.network_elem_identification import UeIdentification
from taf.ue.prisma import prisma
from taf.config.testline.info.ue_attrs import UeAttrs
from .factory import (UDGUpLinkDataTransferFactory, UDGDownLinkDataTransferFactory,
                      UDGUpDownLinkDataTransferFactory,
                      IperfUpLinkDataTransferFactory, IperfDownLinkDataTransferFactory,
                      IperfUpDownLinkDataTransferFactory)
from .prisma_components import PrismaComponents
from .check_throughput import (GNBThroughputChecker,
                               GNBUpLinkThroughputChecker,
                               LSUThroughputChecker,
                               LSUDLTroughputChecker)


class PrismaUe(LteUe):
    """PrismaUe"""

    def __init__(self, name, configuration):
        """
        Definition of Prisma UE

        :param name: name of UE to be stored inside UE object
        """
        super(PrismaUe, self).__init__(name, configuration)
        self.testline_configuration = "tl"
        self._prisma = prisma(self.testline_configuration)
        self.ue_prisma_config = self._prisma.load_config(self._get_prisma_config_file(),
                                                         self.testline_configuration)
        self.tl_config = self.__get_tl_from_robot()
        self._prisma.setup()
        self._components_list = self._get_prisma_components()
        self.__prisma_components = PrismaComponents(
            prisma=self._prisma,
            components_list=self._components_list
        )
        self.prepare_prisma()
        self._prisma_tl_instance = self.__get_prisma_testline_instance()
        self._dl_traffic_factory, self._ul_traffic_factory, self._ul_dl_traffic_factory = self._prepare_traffic()
        self.traffic_instances = []
        ue_pc_ip = self._configuration["data_transfer"]["ue_host"]["addr"]
        ue_pc_port = self._configuration["data_transfer"]["ue_host"]["iperf_port"]
        self.ne_id = UeIdentification(identifiers=[('prisma', (ue_pc_ip, ue_pc_port))],
                                      network_elem_type='UE',
                                      specific_for_tool='prisma')

    @staticmethod
    def __get_tl_from_robot():
        try:
            _robot_utils = importlib.import_module('ute_ue.robot_api.robot_utils')
        except Exception:
            _robot_utils = importlib.import_module('ute_ue.utils.robot_utils')
        return _robot_utils.get_robot_variable('tl')

    def _get_prisma_components(self):
        node_list = []
        for node_name in self.ue_prisma_config.prisma.components.keys():
            logging.info("Component in use: {}".format(node_name))
            node_list.append(node_name)
        logging.info("List prisma components in use: {}".format(node_list))
        return node_list

    def _get_prisma_config_file(self):
        return self._configuration["prisma_config_file"]

    def _get_prisma_scripts_dir(self):
        return self._configuration["scripts_dir"]

    def _get_prisma_sid_filename(self):
        return self._configuration["default_sid_file"]

    def prepare_prisma(self):
        self.__prisma_components.prepare_servers(
            sid=self._get_prisma_sid_filename(),
            config_dir=self._get_prisma_scripts_dir(),
        )

    def __get_prisma_testline_instance(self):
        ue_attrs = UeAttrs(self.tl_config.ues)
        prismas_configs = ue_attrs.get_prisma_ues()
        if not prismas_configs:
            raise Exception("no primsa configuration setting")
        return prismas_configs[0]

    def _prepare_traffic(self):
        logging.debug('Iperf configuration: {}'.format(self._prisma_tl_instance.iperf_details))
        if self._prisma_tl_instance.iperf_details:
            dlfactory = IperfDownLinkDataTransferFactory()
            ulfactory = IperfUpLinkDataTransferFactory()
            uldlfactory = IperfUpDownLinkDataTransferFactory()
            logging.debug("Created Iperf traffic factory.")
        else:
            dlfactory = UDGDownLinkDataTransferFactory()
            ulfactory = UDGUpLinkDataTransferFactory()
            uldlfactory = UDGUpDownLinkDataTransferFactory()
            logging.debug("Created UDG traffic factory.")
        return dlfactory, ulfactory, uldlfactory

    def shutdown(self):
        for _traffic in self.traffic_instances:
            try:
                _traffic.release_iperf_process()
                logging.info("Released {} iperf process.".format(_traffic.name))
            except Exception as e:
                logging.info("Released {} iperf process failed: {}".format(_traffic.name, e))
        self.__prisma_components.stop_s1_link_on_lsu_s1()
        self._prisma.teardown()

    def attach(self, timeout=120):
        """
        run rest api to call attach sce file specified in yaml.
        Only content two check setp: Check attach to MeNB, Check Random access.

        :param timeout: if wait_for_complete is set True, execution will be forced
                        exit when timeout
                        which is predefined in the yaml file
        """
        # TODO: attach log may need to be used for DL traffic (Iperf)
        attach_log = self.__prisma_components.attach(timeout=timeout)
        msg_pattern = re.compile(r'.*IPv4=(.*)\s')
        ue_ips = []
        for msg_item in attach_log:
            ue_ip = msg_pattern.findall(msg_item['message'])
            if ue_ip and ue_ip not in ue_ips:
                ue_ips += ue_ip
        if ue_ips:
            logging.debug("UE IPs:{}".format(ue_ips))
        else:
            logging.warning("Can't found UE IP from attach log.")
        self._configuration['ue_ip'] = ue_ips

    def detach(self, timeout=120):
        """
        run rest api to call dettach sce file specified in yaml

        :param timeout: if wait_for_complete is set True, execution will be forced
                        exit when timeout
        :return: Returns output after running the script
        """
        self.__prisma_components.detach(timeout=timeout)

    def _create_data_transfer(self, name, dt_definition):
        """
        Abstract method for creating data transfer of specific type.

        :param name: name to be assigned to starting transfer. You must use it later on to reference given transfer.
        :param dt_definition: object of DataTransferDefinition that encapsulates all needed parameters.
        :return: data_transfer - object derivered from prisma_data_transfer class
        """
        throughput_check_gnb_connection = self._create_throughput_gnb_checkpointer(self._configuration)
        throughput_check_lsu_connection = self._create_throughput_lsu_checkpointer()

        if dt_definition.direction == "dl":
            traffic = self._dl_traffic_factory.create(
                alias=name,
                dt_definition=dt_definition,
                configuration=self._configuration,
                prisma=self._prisma,
                throughput_checker=LSUDLTroughputChecker(connection=throughput_check_lsu_connection)
            )
        elif dt_definition.direction == "ul":
            traffic = self._ul_traffic_factory.create(
                alias=name,
                dt_definition=dt_definition,
                configuration=self._configuration,
                prisma=self._prisma,
                throughput_checker=GNBUpLinkThroughputChecker(connection=throughput_check_gnb_connection)
            )
        elif dt_definition.direction == "simultaneous_ul_dl":
            traffic = self._ul_dl_traffic_factory.create(
                alias=name,
                dt_definition=dt_definition,
                configuration=self._configuration,
                prisma=self._prisma,
                ul_throughput_checker=GNBUpLinkThroughputChecker(connection=throughput_check_gnb_connection),
                dl_throughput_checker=LSUDLTroughputChecker(connection=throughput_check_lsu_connection)
            )
        else:
            raise Exception("Invalid data transfer direction: {}".format(dt_definition.direction))
        self.traffic_instances.append(traffic)
        return traffic

    @staticmethod
    def _create_throughput_gnb_checkpointer(config):
        throughput_check_config = config['data_transfer']['throughput_checkpointer']
        proxy = None
        if throughput_check_config['proxy']['host']:
            proxy = GNBThroughputChecker.Connection(throughput_check_config['proxy']['host'],
                                                    throughput_check_config['proxy']['user'],
                                                    throughput_check_config['proxy']['password'])

        return GNBThroughputChecker.Connection(throughput_check_config['host'],
                                               throughput_check_config['user'],
                                               throughput_check_config['password'],
                                               proxy=proxy)

    def _create_throughput_lsu_checkpointer(self):
        lsu = self._prisma_tl_instance.lsu_uu_ssh_connection_details
        proxy = None
        if lsu.proxy:
            proxy = LSUThroughputChecker.Connection(address=lsu.proxy.addr,
                                                    username=lsu.proxy.username,
                                                    password=lsu.proxy.password)
        return LSUThroughputChecker.Connection(address=lsu.addr,
                                               username=lsu.username,
                                               password=lsu.password,
                                               proxy=proxy)
